gakc(){return"Ganzes St\xfcck abspielen"},
gb3l(){return"Tippe einen Block an, um diesen Teil zu h\xf6ren."},
gaky(){return"Die Harmonie sehen"},
gb4p(){return"Tippe einen Akkord an, um ihn zu h\xf6ren."},
gOQ(){return"Zuhause (Tonika)"},
gOP(){return"Weg (Subdominante)"},
gOO(){return"Spannung (Dominante)"},
gb3M(){return"Zuhause"},
gb3L(){return"Weg"},
